<template><PageContainer><PageHeader eyebrow="SCR-MON-009" title="Traces monitoring" description="Traces operationnelles structurees, sans payload libre."><template #actions><RouterLink class="mon-pill" to="/app/monitoring"><ArrowLeft/>Retour</RouterLink><button class="mon-btn mon-btn--primary" @click="store.chargerTraces"><RefreshCw/>Actualiser</button></template></PageHeader><SectionBlock v-if="canCapture" title="Capturer une trace" description="Capture typee selon MON-17."><form class="mon-grid" @submit.prevent="capture"><label class="mon-field"><span>Trace ID</span><input v-model="form.traceId" maxlength="160"/></label><label class="mon-field"><span>Type</span><select v-model="form.type"><option v-for="t in types" :key="t">{{t}}</option></select></label><label class="mon-field"><span>Operation</span><input v-model="form.operation" maxlength="255"/></label><label class="mon-field"><span>Duree (ms)</span><input v-model.number="form.dureeMillisecondes" type="number" min="0"/></label><label class="mon-field"><span>Succes</span><select v-model="successText"><option value="true">Oui</option><option value="false">Non</option></select></label><label class="mon-field"><span>Correlation ID</span><input v-model="form.correlationId" maxlength="128"/></label><label class="mon-field mon-field--full"><span>Message optionnel</span><textarea v-model="form.message" maxlength="2000" rows="2"></textarea></label><div class="mon-actions mon-field--full"><button class="mon-btn mon-btn--primary" type="submit">Capturer</button></div></form></SectionBlock><LoadingState v-if="store.state.status==='loading'" title="Traces en cours" message="Actualisation des traces."/><ErrorState v-else-if="store.state.status==='error'" title="Traces indisponibles" :message="store.state.errorMessage??'Erreur technique.'"/><SectionBlock v-else title="Traces" description="Historique structure des operations observees."><MonitoringEmptyState v-if="!store.state.traces.length" title="Aucune trace" message="Aucune trace n'est disponible."/><div v-else class="mon-table-wrap"><table class="mon-table"><thead><tr><th>Trace</th><th>Type</th><th>Operation</th><th>Resultat</th><th>Duree</th><th>Capture</th></tr></thead><tbody><tr v-for="t in store.state.traces" :key="t.identifiant"><td><strong>{{t.identifiant}}</strong></td><td>{{t.type}}</td><td>{{t.operation}}</td><td>{{t.succes?'Succes':'Echec'}}</td><td>{{t.dureeMillisecondes}} ms</td><td>{{date(t.captureeLe)}}</td></tr></tbody></table></div></SectionBlock></PageContainer></template>
<script setup lang="ts">import {reactive,ref} from 'vue';import {RouterLink} from 'vue-router';import {ArrowLeft,RefreshCw} from 'lucide-vue-next';import PageContainer from '../../../shared/layout/PageContainer.vue';import PageHeader from '../../../shared/layout/PageHeader.vue';import SectionBlock from '../../../shared/layout/SectionBlock.vue';import LoadingState from '../../../shared/ui/LoadingState.vue';import ErrorState from '../../../shared/ui/ErrorState.vue';import MonitoringEmptyState from '../components/MonitoringEmptyState.vue';import {hasMonitoringPermission} from '../access/monitoring-access';import {required,finiteNonNegative} from '../validation/monitoring-form.validation';import type {TraceType} from '../models/monitoring.model';import {useMonitoringStore} from '../stores/monitoring.store';import '../monitoring.css';const store=useMonitoringStore();const canCapture=hasMonitoringPermission('monitoring.traces.create');const types:TraceType[]=['REQUEST','JOB','EVENT','DIAGNOSTIC','FORENSIC'];const form=reactive<{traceId:string;type:TraceType;operation:string;dureeMillisecondes:number;message:string;correlationId:string}>({traceId:'',type:'REQUEST',operation:'',dureeMillisecondes:0,message:'',correlationId:''}),successText=ref('true');async function capture(){if(required(form.traceId,'Trace ID')||required(form.operation,'Operation',255)||required(form.correlationId,'Correlation ID',128)||finiteNonNegative(form.dureeMillisecondes,'Duree'))return;await store.capturerTrace({...form,succes:successText.value==='true',message:form.message.trim()||undefined})}const date=(v:string)=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));</script>
